const counterModule=function(){let n=0;return{increment:function(){return++n},decrement:function(){return--n},reset:function(){return n=0,n},value:function(){return n}}}();print("initial:",counterModule.value()),print("inc:",counterModule.increment()),print("inc:",counterModule.increment()),print("inc:",counterModule.increment()),print("dec:",counterModule.decrement()),print("reset:",counterModule.reset()),print("final value:",counterModule.value());const named=function n(e){return e<=1?1:e*n(e-1)}(5);print("named IIFE factorial(5)="+named);